"""Class 10 Maths Ch 2 - Polynomials (graded banks)."""
from mg import *

SLUG, NAME, CHNO = "Polynomials", "Polynomials", 2

def P(cs): return "$" + poly(cs) + "$"          # polynomial in $ $
def PT(cs): return poly(cs)                       # polynomial tex
def QR(r1, r2, a=1): return from_roots(r1, r2, a=a)
def CB(r1, r2, r3, a=1): return from_roots(r1, r2, r3, a=a)
def S(r1, r2): return F(r1) + F(r2)
def Pr(r1, r2): return F(r1) * F(r2)
def zk(r, k): return -(r * r + k * r)    # constant term c so that r is a zero of x^2+kx+c
def kq(r, k): return f"x^2{k:+d}x{zk(r, k):+d}".replace("+1x", "+x").replace("-1x", "-x")
def zero_k(r, k, extra=""):
    return (f"If ${r}$ is a zero of the polynomial $x^2+kx{zk(r,k):+d}$, find the value of $k$" + extra + ".",
            f"$p({r})=0$: ${r*r}{r*k:+d}{zk(r,k):+d}=0$ gives $k={k}$ (2)" + ((f"; sum of zeroes $=-k={-k}$, so the other zero is ${-k-r}$ (1)." ) if extra else " (1)."))

def zl(*rs): return ", ".join(t(r) for r in rs)
def srt(*rs): return sorted(F(r) for r in rs)

